+ */
+export interface AgentDefinition {
+	_ulid: string;
+	id: string;
+	name: string;
+	description?: string;
+	adapter?: string;
+	dispatch: Array<{
+		on: string;
+		filter?: {
+			automation?: string;
+			tags?: string[];
+			priority?: number;
+		};
+	}>;
