  1	<script lang="ts">
  2		// AC: @ui-agent-dispatch ac-1 — Agent definitions with name, triggers, active/completed counts
  3		// AC: @ui-agent-dispatch ac-2 — Dispatch running: status, stop button, active invocations
  4		// AC: @ui-agent-dispatch ac-3 — Dispatch stopped: status shown, no active invocations
  5		import { onMount, onDestroy } from 'svelte';
  6		import {
  7			fetchAgentStatus,
  8			fetchAgentDefinitions,
  9			controlDispatch,
 10			type AgentDefinition,
 11			type AgentDispatchStatus,
 12			type ActiveInvocation
 13		} from '$lib/api';
 14		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 15		import { isStaticMode, ReadOnlyModeError } from '$lib/stores/mode.svelte';
 16		import { getProjectVersion } from '$lib/stores/project.svelte';
 17		import AgentCard from '$lib/components/agents/AgentCard.svelte';
 18		import DispatchStatusComponent from '$lib/components/agents/DispatchStatus.svelte';
 19		import ActiveInvocationRow from '$lib/components/agents/ActiveInvocationRow.svelte';
 20		import { Separator } from '$lib/components/ui/separator';
 21		import { Skeleton } from '$lib/components/ui/skeleton';
 22		import Bot from '@lucide/svelte/icons/bot';
 23		import Zap from '@lucide/svelte/icons/zap';
 24	
 25		let agentDefinitions = $state<AgentDefinition[]>([]);
 26		let dispatchStatus = $state<AgentDispatchStatus | null>(null);
 27		let loading = $state(true);
 28		let error = $state('');
 29		let isToggling = $state(false);
 30	
 31		// Screen reader announcement for live invocation updates
 32		let invocationAnnouncement = $state('');
 33	
 34		// Track completed invocations per agent (incremented by WebSocket events)
 35		let completedCounts = $state<Record<string, number>>({});
 36	
 37		// Derive active counts per agent from dispatch status
 38		let activeCounts = $derived.by(() => {
 39			const counts: Record<string, number> = {};
 40			if (dispatchStatus?.active_invocations) {
 41				for (const inv of dispatchStatus.active_invocations) {
 42					counts[inv.agent_id] = (counts[inv.agent_id] || 0) + 1;
 43				}
 44			}
 45			return counts;
 46		});
 47	
 48		// Reload on project change
 49		$effect(() => {
 50			const version = getProjectVersion();
 51			if (version > 0) {
 52				loadData();
 53			}
 54		});
 55	
 56		async function loadData() {
 57			loading = true;
 58			error = '';
 59	
 60			try {
 61				const [statusResult, defsResult] = await Promise.all([
 62					fetchAgentStatus(),
 63					fetchAgentDefinitions()
 64				]);
 65				dispatchStatus = statusResult;
 66				agentDefinitions = defsResult.items;
 67			} catch (err) {
 68				error = err instanceof Error ? err.message : 'Failed to load agent data';
 69				console.error('Error loading agent data:', err);
 70			} finally {
 71				loading = false;
 72			}
 73		}
 74	
 75		async function handleStartDispatch() {
 76			if (isStaticMode()) return;
 77			isToggling = true;
 78			error = '';
 79	
 80			try {
 81				const result = await controlDispatch('start');
 82				// Refresh full status after toggle
 83				dispatchStatus = await fetchAgentStatus();
 84			} catch (err) {
 85				if (err instanceof ReadOnlyModeError) {
 86					error = err.message;
 87				} else {
 88					error = err instanceof Error ? err.message : 'Failed to start dispatch';
 89				}
 90			} finally {
 91				isToggling = false;
 92			}
 93		}
 94	
 95		async function handleStopDispatch() {
 96			if (isStaticMode()) return;
 97			isToggling = true;
 98			error = '';
 99	
100			try {
101				const result = await controlDispatch('stop');
102				// Refresh full status after toggle
103				dispatchStatus = await fetchAgentStatus();
104			} catch (err) {
105				if (err instanceof ReadOnlyModeError) {
106					error = err.message;
107				} else {
108					error = err instanceof Error ? err.message : 'Failed to stop dispatch';
109				}
110			} finally {
111				isToggling = false;
112			}
113		}
114	
115		function handleAgentEvent(event: any) {
116			if (event.event === 'agent_invocation') {
117				const data = event.data;
118				if (data.status === 'completed' || data.status === 'failed') {
119					completedCounts = {
120						...completedCounts,
121						[data.agent_id]: (completedCounts[data.agent_id] || 0) + 1
122					};
123				}
124				// Announce change to screen readers
125				const agentLabel = data.agent_id || 'Agent';
126				if (data.status === 'started') {
127					invocationAnnouncement = `${agentLabel} invocation started`;
128				} else if (data.status === 'completed') {
129					invocationAnnouncement = `${agentLabel} invocation completed`;
130				} else if (data.status === 'failed') {
131					invocationAnnouncement = `${agentLabel} invocation failed`;
132				}
133				// Refresh status to update active invocations
134				fetchAgentStatus()
135					.then((status) => {
136						dispatchStatus = status;
137					})
138					.catch((err) => console.error('Error refreshing agent status:', err));
139			}
140		}
141	
142		onMount(() => {
143			loadData();
144			subscribe(['agents']);
145			on('agents', handleAgentEvent);
146		});
147	
148		onDestroy(() => {
149			off('agents', handleAgentEvent);
150			unsubscribe(['agents']);
151		});
152	</script>
153	
154	<div class="flex flex-col gap-6 p-6">
155		<div>
156			<h1 class="text-3xl font-bold mb-2">Agents</h1>
157			<p class="text-muted-foreground">Agent definitions and dispatch engine status.</p>
158		</div>
159	
160		<!-- Error State -->
161		{#if error}
