531	
532		const response = await fetch(`${API_BASE}/api/triage/${ref}/override`, {
533			method: 'POST',
534			headers: {
535				'Content-Type': 'application/json',
536				...getProjectHeaders()
537			},
538			body: JSON.stringify(data)
539		});
540		if (!response.ok) {
541			await handleResponseError(response);
542		}
543	
544		return response.json();
545	}
