547	// ============================================================
548	// Agent & Dispatch API Functions
549	// AC: @ui-agent-dispatch ac-1, ac-2, ac-3
550	// ============================================================
551	
552	/**
553	 * Agent definition from GET /api/meta/agents
554	 */
555	export interface AgentDefinition {
556		_ulid: string;
557		id: string;
558		name: string;
559		description?: string;
560		adapter?: string;
561		dispatch: Array<{
562			on: string;
563			filter?: {
564				automation?: string;
565				tags?: string[];
566				priority?: number;
567			};
568		}>;
569		capabilities: string[];
