571		skills: string[];
572		budget?: {
573			max_tasks?: number;
574			timeout_minutes?: number;
575		};
576		concurrency: {
577			max_concurrent: number;
578		};
579		auto_approve: boolean;
580	}
581	
582	/**
583	 * Active invocation from GET /api/agent/status
584	 */
585	export interface ActiveInvocation {
586		session_id: string;
587		agent_id: string;
588		task_ref: string | null;
589		elapsed_ms: number;
590	}
591	
592	/**
593	 * Agent dispatch status from GET /api/agent/status
594	 */
595	export interface AgentDispatchStatus {
596		dispatch_enabled: boolean;
597		active_invocations: ActiveInvocation[];
598		queue_depth: number;
599		agent_definitions: Array<{
600			id: string;
601			name: string;
602			adapter: string;
603		}>;
604	}
605	
606	/**
607	 * Fetch agent dispatch status (dispatch state + active invocations)
608	 * AC: @ui-agent-dispatch ac-1, ac-2, ac-3
609	 */
610	export async function fetchAgentStatus(): Promise<AgentDispatchStatus> {
611		const response = await fetch(`${API_BASE}/api/agent/status`, {
612			headers: getProjectHeaders()
613		});
614		if (!response.ok) {
615			await handleResponseError(response);
616		}
617		return response.json();
618	}
619	
620	/**
621	 * Fetch full agent definitions from meta
622	 * AC: @ui-agent-dispatch ac-1
623	 */
624	export async function fetchAgentDefinitions(): Promise<{ items: AgentDefinition[]; total: number }> {
625		const response = await fetch(`${API_BASE}/api/meta/agents`, {
626			headers: getProjectHeaders()
627		});
628		if (!response.ok) {
629			await handleResponseError(response);
630		}
631		return response.json();
632	}
